package com.lingyifan.lab.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.lingyifan.lab.api.LabDtos.*; import com.lingyifan.lab.domain.*; import com.lingyifan.lab.mapper.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.time.*; import java.util.*;
@Service public class LabService {
 private final EquipmentMapper equipment; private final ReservationMapper reservations; private final RepairOrderMapper repairs;
 public LabService(EquipmentMapper e,ReservationMapper r,RepairOrderMapper repairs){equipment=e;reservations=r;this.repairs=repairs;}
 @Transactional public Equipment add(EquipmentInput in){Equipment e=new Equipment(null,in.assetCode(),in.name(),in.category(),in.labRoom(),"AVAILABLE");equipment.insert(e);return e;}
 public List<Equipment> equipment(){return equipment.selectList(new LambdaQueryWrapper<Equipment>().orderByAsc(Equipment::getLabRoom));}
 @Transactional public Reservation reserve(ReservationInput in){if(!in.endAt().isAfter(in.startAt()))throw new IllegalArgumentException("结束时间必须晚于开始时间");Equipment e=needEquipment(in.equipmentId());if(!"AVAILABLE".equals(e.getStatus()))throw new IllegalStateException("设备当前不可预约");boolean conflict=reservations.selectCount(new LambdaQueryWrapper<Reservation>().eq(Reservation::getEquipmentId,in.equipmentId()).in(Reservation::getStatus,List.of("PENDING","APPROVED")).lt(Reservation::getStartAt,in.endAt()).gt(Reservation::getEndAt,in.startAt()))>0;if(conflict)throw new IllegalStateException("该时间段已经被预约");Reservation r=new Reservation();r.setEquipmentId(in.equipmentId());r.setStudentId(in.studentId());r.setStartAt(in.startAt());r.setEndAt(in.endAt());r.setPurpose(in.purpose());r.setStatus("PENDING");r.setCreatedAt(LocalDateTime.now());reservations.insert(r);return r;}
 @Transactional public Reservation review(Long id,ReviewInput in){Reservation r=needReservation(id);if(!"PENDING".equals(r.getStatus()))throw new IllegalStateException("只能审核待审批预约");r.setStatus(in.decision());r.setReviewNote(in.note());reservations.updateById(r);return r;}
 @Transactional public Reservation checkOut(Long id){Reservation r=needReservation(id);if(!"APPROVED".equals(r.getStatus()))throw new IllegalStateException("预约未批准");r.setStatus("IN_USE");reservations.updateById(r);Equipment e=needEquipment(r.getEquipmentId());e.setStatus("IN_USE");equipment.updateById(e);return r;}
 @Transactional public Reservation returnBack(Long id){Reservation r=needReservation(id);if(!"IN_USE".equals(r.getStatus()))throw new IllegalStateException("设备没有借出");r.setStatus("COMPLETED");reservations.updateById(r);Equipment e=needEquipment(r.getEquipmentId());e.setStatus("AVAILABLE");equipment.updateById(e);return r;}
 @Transactional public RepairOrder report(RepairInput in){Equipment e=needEquipment(in.equipmentId());e.setStatus("MAINTENANCE");equipment.updateById(e);RepairOrder o=new RepairOrder();o.setEquipmentId(in.equipmentId());o.setReporterId(in.reporterId());o.setDescription(in.description());o.setStatus("OPEN");o.setCreatedAt(LocalDateTime.now());repairs.insert(o);return o;}
 @Transactional public RepairOrder resolve(Long id,ResolveInput in){RepairOrder o=repairs.selectById(id);if(o==null)throw new IllegalArgumentException("维修单不存在");o.setStatus("RESOLVED");o.setResolution(in.resolution());o.setResolvedAt(LocalDateTime.now());repairs.updateById(o);Equipment e=needEquipment(o.getEquipmentId());e.setStatus("AVAILABLE");equipment.updateById(e);return o;}
 public List<Reservation> reservations(){return reservations.selectList(new LambdaQueryWrapper<Reservation>().orderByDesc(Reservation::getCreatedAt));}
 public List<RepairOrder> repairs(){return repairs.selectList(new LambdaQueryWrapper<RepairOrder>().orderByDesc(RepairOrder::getCreatedAt));}
 public Map<String,Object> dashboard(){return Map.of("equipment",equipment.selectCount(null),"available",equipment.selectCount(new LambdaQueryWrapper<Equipment>().eq(Equipment::getStatus,"AVAILABLE")),"pendingReservations",reservations.selectCount(new LambdaQueryWrapper<Reservation>().eq(Reservation::getStatus,"PENDING")),"openRepairs",repairs.selectCount(new LambdaQueryWrapper<RepairOrder>().eq(RepairOrder::getStatus,"OPEN")));}
 private Equipment needEquipment(Long id){Equipment e=equipment.selectById(id);if(e==null)throw new IllegalArgumentException("设备不存在");return e;} private Reservation needReservation(Long id){Reservation r=reservations.selectById(id);if(r==null)throw new IllegalArgumentException("预约不存在");return r;}
}
